class OrderService {
  process(order, type) {
    if (type === 'PAYPAL') {
      const pp = new PayPalSDK();
      pp.pay(order.amount);
    } else if (type === 'STRIPE') {
      const st = new StripeSDK();
      st.charge(order.amount);
    }
  }
}

